--------------------------------------------------------------------------------
-- AfwaahTracker :: 01_schema.sql
-- Core relational tables.
--
-- Concepts demonstrated:
--   * relational model / approx. Third Normal Form (lookup tables for
--     platforms, categories, entities and keywords; junction tables for M:N)
--   * PRIMARY KEY  (entity integrity)
--   * IDENTITY     (surrogate keys generated by Oracle)
--   * NOT NULL / DEFAULT (domain integrity)
--   * self-referencing columns (SOURCES.derived_from_source_id,
--     CLAIM_VARIANTS.parent_variant_id)
-- Foreign keys, UNIQUE and CHECK constraints are added in 02_constraints.sql.
--------------------------------------------------------------------------------
SET DEFINE OFF
PROMPT Creating tables ...

-- Platforms where a source appeared (news site, forum, social network ...)
CREATE TABLE platforms (
    platform_id     NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,
    platform_name   VARCHAR2(80)  NOT NULL,
    platform_type   VARCHAR2(20)  NOT NULL,
    base_url        VARCHAR2(300),
    created_at      TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT pk_platforms PRIMARY KEY (platform_id)
);

-- Claim categories (separate table keeps CLAIMS in 3NF)
CREATE TABLE categories (
    category_id     NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,
    category_name   VARCHAR2(60)  NOT NULL,
    description     VARCHAR2(300),
    CONSTRAINT pk_categories PRIMARY KEY (category_id)
);

-- Registry of automated, structured ingestion endpoints
CREATE TABLE ingestion_sources (
    ingestion_source_id     NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,
    source_name             VARCHAR2(120) NOT NULL,
    source_type             VARCHAR2(20)  NOT NULL,
    endpoint_url            VARCHAR2(1000) NOT NULL,
    platform_id             NUMBER        NOT NULL,
    default_category_id     NUMBER        NOT NULL,
    enabled                 CHAR(1)       DEFAULT 'Y' NOT NULL,
    fetch_interval_minutes  NUMBER(6)     DEFAULT 60 NOT NULL,
    max_items               NUMBER(4)     DEFAULT 25 NOT NULL,
    last_fetched_at         TIMESTAMP,
    created_at              TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT pk_ingestion_sources PRIMARY KEY (ingestion_source_id)
);

-- One row per ingestion run of one ingestion source
CREATE TABLE ingestion_log (
    log_id                  NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,
    ingestion_source_id     NUMBER        NOT NULL,
    started_at              TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
    completed_at            TIMESTAMP,
    records_fetched         NUMBER(6)     DEFAULT 0 NOT NULL,
    records_inserted        NUMBER(6)     DEFAULT 0 NOT NULL,
    records_skipped         NUMBER(6)     DEFAULT 0 NOT NULL,
    records_matched         NUMBER(6)     DEFAULT 0 NOT NULL,
    status                  VARCHAR2(12)  DEFAULT 'RUNNING' NOT NULL,
    error_message           VARCHAR2(1000),
    CONSTRAINT pk_ingestion_log PRIMARY KEY (log_id)
);

-- Every individual published item (article, post, story, forward ...)
CREATE TABLE sources (
    source_id               NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,
    platform_id             NUMBER        NOT NULL,
    ingestion_source_id     NUMBER,
    publisher               VARCHAR2(200) NOT NULL,
    author                  VARCHAR2(200),
    source_title            VARCHAR2(1000) NOT NULL,
    source_url              VARCHAR2(1000) NOT NULL,
    linked_url              VARCHAR2(1000),
    external_source_id      VARCHAR2(100),
    published_at            TIMESTAMP     NOT NULL,
    fetched_at              TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
    snippet                 VARCHAR2(4000),
    engagement_count        NUMBER(12)    DEFAULT 0 NOT NULL,
    source_status           VARCHAR2(20)  DEFAULT 'ACTIVE' NOT NULL,
    origin_type             VARCHAR2(12)  DEFAULT 'AUTOMATED' NOT NULL,
    derived_from_source_id  NUMBER,
    provenance_note         VARCHAR2(500),
    created_at              TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT pk_sources PRIMARY KEY (source_id)
);

-- Canonical claim families
CREATE TABLE claims (
    claim_id            NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,
    canonical_claim     VARCHAR2(500) NOT NULL,
    category_id         NUMBER        NOT NULL,
    status              VARCHAR2(20)  DEFAULT 'UNVERIFIED' NOT NULL,
    claim_origin        VARCHAR2(12)  DEFAULT 'AUTOMATED' NOT NULL,
    summary             VARCHAR2(1000),
    created_at          TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
    updated_at          TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT pk_claims PRIMARY KEY (claim_id)
);

-- One structured version of a claim as it appeared in one source
CREATE TABLE claim_variants (
    variant_id          NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,
    claim_id            NUMBER        NOT NULL,
    source_id           NUMBER        NOT NULL,
    parent_variant_id   NUMBER,
    variant_text        VARCHAR2(1000) NOT NULL,
    actor               VARCHAR2(200),
    action              VARCHAR2(100),
    target_object       VARCHAR2(200),
    location_name       VARCHAR2(200),
    event_name          VARCHAR2(200),
    claimed_date        VARCHAR2(80),
    quantity_value      VARCHAR2(80),
    certainty           VARCHAR2(12)  DEFAULT 'UNSTATED' NOT NULL,
    attribution         VARCHAR2(200),
    match_score         NUMBER(5,2)   DEFAULT 100 NOT NULL,
    match_method        VARCHAR2(20)  DEFAULT 'CURATED' NOT NULL,
    match_breakdown     VARCHAR2(400),
    lineage_basis       VARCHAR2(20)  DEFAULT 'CURATED' NOT NULL,
    created_at          TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT pk_claim_variants PRIMARY KEY (variant_id)
);

-- Dictionary of known named entities
CREATE TABLE entities (
    entity_id       NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,
    entity_name     VARCHAR2(200) NOT NULL,
    entity_type     VARCHAR2(20)  NOT NULL,
    description     VARCHAR2(500),
    created_at      TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT pk_entities PRIMARY KEY (entity_id)
);

-- Alternative spellings / names of an entity (1:N)
CREATE TABLE entity_aliases (
    alias_id        NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,
    entity_id       NUMBER        NOT NULL,
    alias_text      VARCHAR2(200) NOT NULL,
    CONSTRAINT pk_entity_aliases PRIMARY KEY (alias_id)
);

-- M:N claims <-> entities
CREATE TABLE claim_entities (
    claim_id        NUMBER NOT NULL,
    entity_id       NUMBER NOT NULL,
    detected_by     VARCHAR2(12) DEFAULT 'CURATED' NOT NULL,
    created_at      TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT pk_claim_entities PRIMARY KEY (claim_id, entity_id)
);

-- Capitalised phrases seen in ingested text that are NOT in the dictionary.
-- Their type is deliberately not guessed.
CREATE TABLE entity_candidates (
    candidate_id          NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,
    candidate_text        VARCHAR2(200) NOT NULL,
    occurrence_count      NUMBER(8) DEFAULT 1 NOT NULL,
    first_seen_source_id  NUMBER,
    first_seen_at         TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
    last_seen_at          TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
    status                VARCHAR2(12) DEFAULT 'PENDING' NOT NULL,
    CONSTRAINT pk_entity_candidates PRIMARY KEY (candidate_id)
);

-- Keyword dictionary
CREATE TABLE keywords (
    keyword_id      NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,
    keyword_text    VARCHAR2(80) NOT NULL,
    keyword_origin  VARCHAR2(12) DEFAULT 'CURATED' NOT NULL,
    created_at      TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT pk_keywords PRIMARY KEY (keyword_id)
);

-- M:N claims <-> keywords
CREATE TABLE claim_keywords (
    claim_id        NUMBER NOT NULL,
    keyword_id      NUMBER NOT NULL,
    weight          NUMBER(3) DEFAULT 1 NOT NULL,
    CONSTRAINT pk_claim_keywords PRIMARY KEY (claim_id, keyword_id)
);

-- Structured signature of a claim (1:1 with CLAIMS)
CREATE TABLE fingerprints (
    fingerprint_id      NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,
    claim_id            NUMBER NOT NULL,
    core_assertion      VARCHAR2(500) NOT NULL,
    sentiment           VARCHAR2(10),
    emotional_hook      VARCHAR2(200),
    manipulation_marker VARCHAR2(200),
    source_pattern      VARCHAR2(200),
    notes               VARCHAR2(1000),
    is_curated          CHAR(1) DEFAULT 'N' NOT NULL,
    created_at          TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT pk_fingerprints PRIMARY KEY (fingerprint_id)
);

-- Mutation Ledger: one row per structured component that changed
-- between a parent variant and a child variant.
CREATE TABLE claim_mutations (
    mutation_id         NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,
    claim_id            NUMBER        NOT NULL,
    parent_variant_id   NUMBER        NOT NULL,
    child_variant_id    NUMBER        NOT NULL,
    changed_component   VARCHAR2(20)  NOT NULL,
    old_value           VARCHAR2(200),
    new_value           VARCHAR2(200),
    is_escalation       CHAR(1) DEFAULT 'N' NOT NULL,
    detected_at         TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
    CONSTRAINT pk_claim_mutations PRIMARY KEY (mutation_id)
);

-- Generic audit trail written by triggers
CREATE TABLE audit_log (
    audit_id        NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY,
    table_name      VARCHAR2(40)  NOT NULL,
    operation       VARCHAR2(10)  NOT NULL,
    record_id       NUMBER,
    changed_by      VARCHAR2(128) DEFAULT USER NOT NULL,
    changed_at      TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
    details         VARCHAR2(1000),
    CONSTRAINT pk_audit_log PRIMARY KEY (audit_id)
);

PROMPT Tables created.
